import { Badge } from '@/components/ui/badge';
import { LinkButton } from '@/components/ui/button';
import { CardAction, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { EmptyContent, EmptyDescription, EmptyHeader, EmptyTitle } from '@/components/ui/empty';

/** One section action: its Writer label and where it goes. */
export interface SectionAction { label: string; href: string }

/** The inputs of `sections.section-header`: the contract's copy fields, display-ready. */
export interface SectionHeaderInput {
  eyebrow?: string;
  heading: string;
  description?: string;
  actions?: readonly SectionAction[];
  /** `align.start` (the stock card header, actions at the end) or `align.center` (the stock empty header). */
  align?: 'start' | 'center';
}

/** `sections.section-header`: a section's eyebrow, heading, description and at most two actions, composed of stock aria-nova parts only. */
export default function SectionHeaderSection({ eyebrow, heading, description, actions = [], align = 'start', ...provenance }: SectionHeaderInput & { [marker: `data-clossys-${string}`]: string }) {
  const links = actions.slice(0, 2).map((action, index) => <LinkButton key={action.href} href={action.href} variant={index === 0 ? 'default' : 'outline'}>{action.label}</LinkButton>);
  if (align === 'center') return <EmptyHeader data-align="center" {...provenance}>
    {eyebrow ? <Badge variant="secondary">{eyebrow}</Badge> : null}
    <EmptyTitle role="heading" aria-level={2}>{heading}</EmptyTitle>
    {description ? <EmptyDescription>{description}</EmptyDescription> : null}
    {links.length ? <EmptyContent>{links}</EmptyContent> : null}
  </EmptyHeader>;
  return <CardHeader data-align="start" {...provenance}>
    {eyebrow ? <CardDescription><Badge variant="secondary">{eyebrow}</Badge></CardDescription> : null}
    <CardTitle role="heading" aria-level={2}>{heading}</CardTitle>
    {description ? <CardDescription>{description}</CardDescription> : null}
    {links.length ? <CardAction>{links}</CardAction> : null}
  </CardHeader>;
}
